import React, { useState, useEffect } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  SafeAreaView,
  TextInput,
  Alert,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const WorkoutScreen = ({ navigation }) => {
  const [currentWorkout, setCurrentWorkout] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [exercises, setExercises] = useState([]);
  const [workoutRatings, setWorkoutRatings] = useState({
    beforeMood: 5,
    beforeEnergy: 5,
    afterMood: 5,
    afterEnergy: 5,
    workoutRating: 5,
  });

  const exerciseCategories = {
    Chest: [
      'Incline Bench Press (Smith)', 'Bench Press', 'Cable Fly (Low)', 
      'Cable Fly (Middle)', 'Cable Fly (High)', 'Bench Press (Smith)', 
      'Incline Bench Press', 'Incline Dumbbell Bench Press', 
      'Dumbbell Bench Press', 'Decline Bench Press'
    ],
    Back: [
      'Lat Pulldown (Wide-grip)', 'Lat Pulldown (Close-grip)', 'Deadlift', 
      'Deadlift (Smith)', 'Upright Barbell Row (Smith)', 'Upright Barbell Row', 
      'Single Arm Dumbbell Row', 'Bent-Over Rows (Smith)', 'Bent-Over Rows', 
      'Pull-Ups', 'Pull-Ups (Weighted)'
    ],
    Legs: [
      'Barbell Squat', 'Barbell Squat (Smith)', 'Seated Leg Press', 
      'Seated Calf Raise', 'Leg Extension'
    ],
    Shoulders: [
      'Standing Barbell Shoulder Press', 'Seated Barbell Shoulder Press (Smith)', 
      'Seated Dumbbell Shoulder Press', 'Face Pulls', 'Bent Over Reverse Fly', 
      'Lateral Raise', 'Arnold Press'
    ],
    Bicep: [
      'Standing Barbell Bicep Curl', 'Preacher Curls', 'Hammer Curls', 
      'Incline Dumbbell Curls'
    ],
    Tricep: [
      'Tricep Pushdowns', 'Tricep Dips', 'Skullcrushers'
    ],
    Abs: [
      'Hanging Leg Raises', 'Upright Ab Pulldowns'
    ],
  };

  const startNewWorkout = () => {
    const workout = {
      id: Date.now(),
      startTime: new Date(),
      type: 'Weightlifting',
      exercises: [],
      ratings: { ...workoutRatings },
    };
    setCurrentWorkout(workout);
    showPreWorkoutRatings();
  };

  const showPreWorkoutRatings = () => {
    Alert.alert(
      'Pre-Workout Check-in',
      'How are you feeling before your workout?',
      [
        {
          text: 'Skip',
          onPress: () => {},
        },
        {
          text: 'Rate',
          onPress: () => {
            // TODO: Show rating modal
            console.log('Show pre-workout ratings');
          },
        },
      ]
    );
  };

  const addExercise = (exerciseName) => {
    const newExercise = {
      id: Date.now(),
      name: exerciseName,
      sets: [],
      notes: '',
    };
    setExercises([...exercises, newExercise]);
    setSelectedCategory(null);
  };

  const addSet = (exerciseId) => {
    const updatedExercises = exercises.map(exercise => {
      if (exercise.id === exerciseId) {
        const newSet = {
          id: Date.now(),
          reps: '',
          weight: '',
          completed: false,
        };
        return {
          ...exercise,
          sets: [...exercise.sets, newSet],
        };
      }
      return exercise;
    });
    setExercises(updatedExercises);
  };

  const updateSet = (exerciseId, setId, field, value) => {
    const updatedExercises = exercises.map(exercise => {
      if (exercise.id === exerciseId) {
        const updatedSets = exercise.sets.map(set => {
          if (set.id === setId) {
            return { ...set, [field]: value };
          }
          return set;
        });
        return { ...exercise, sets: updatedSets };
      }
      return exercise;
    });
    setExercises(updatedExercises);
  };

  const finishWorkout = () => {
    if (currentWorkout) {
      const finishedWorkout = {
        ...currentWorkout,
        endTime: new Date(),
        exercises: exercises,
        duration: Math.round((new Date() - currentWorkout.startTime) / 60000),
      };
      
      // TODO: Save to local storage
      console.log('Saving workout:', finishedWorkout);
      
      setCurrentWorkout(null);
      setExercises([]);
      setSelectedCategory(null);
      
      Alert.alert('Workout Complete!', 'Great job! Your workout has been saved.');
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <ScrollView style={styles.scrollView}>
        {!currentWorkout ? (
          // Workout not started
          <View style={styles.startContainer}>
            <Text style={styles.title}>Start a New Workout</Text>
            <TouchableOpacity style={styles.startButton} onPress={startNewWorkout}>
              <Ionicons name="play" size={24} color="#fff" />
              <Text style={styles.startButtonText}>Begin Workout</Text>
            </TouchableOpacity>
          </View>
        ) : (
          // Workout in progress
          <View style={styles.workoutContainer}>
            <View style={styles.workoutHeader}>
              <Text style={styles.workoutTitle}>Workout in Progress</Text>
              <Text style={styles.workoutTime}>
                {Math.round((new Date() - currentWorkout.startTime) / 60000)} min
              </Text>
            </View>

            {/* Exercise Categories */}
            <View style={styles.categoriesContainer}>
              <Text style={styles.sectionTitle}>Add Exercise</Text>
              <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                {Object.keys(exerciseCategories).map((category) => (
                  <TouchableOpacity
                    key={category}
                    style={[
                      styles.categoryButton,
                      selectedCategory === category && styles.selectedCategory,
                    ]}
                    onPress={() => setSelectedCategory(category)}
                  >
                    <Text style={[
                      styles.categoryText,
                      selectedCategory === category && styles.selectedCategoryText,
                    ]}>
                      {category}
                    </Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
            </View>

            {/* Exercise List */}
            {selectedCategory && (
              <View style={styles.exercisesContainer}>
                <Text style={styles.sectionTitle}>{selectedCategory} Exercises</Text>
                {exerciseCategories[selectedCategory].map((exercise) => (
                  <TouchableOpacity
                    key={exercise}
                    style={styles.exerciseButton}
                    onPress={() => addExercise(exercise)}
                  >
                    <Text style={styles.exerciseText}>{exercise}</Text>
                    <Ionicons name="add" size={20} color="#007AFF" />
                  </TouchableOpacity>
                ))}
              </View>
            )}

            {/* Current Exercises */}
            {exercises.length > 0 && (
              <View style={styles.currentExercises}>
                <Text style={styles.sectionTitle}>Current Exercises</Text>
                {exercises.map((exercise) => (
                  <View key={exercise.id} style={styles.exerciseCard}>
                    <View style={styles.exerciseHeader}>
                      <Text style={styles.exerciseName}>{exercise.name}</Text>
                      <TouchableOpacity onPress={() => addSet(exercise.id)}>
                        <Ionicons name="add-circle" size={24} color="#007AFF" />
                      </TouchableOpacity>
                    </View>
                    
                    {exercise.sets.map((set, index) => (
                      <View key={set.id} style={styles.setRow}>
                        <Text style={styles.setNumber}>Set {index + 1}</Text>
                        <TextInput
                          style={styles.input}
                          placeholder="Reps"
                          keyboardType="numeric"
                          value={set.reps.toString()}
                          onChangeText={(value) => updateSet(exercise.id, set.id, 'reps', parseInt(value) || 0)}
                        />
                        <TextInput
                          style={styles.input}
                          placeholder="Weight"
                          keyboardType="numeric"
                          value={set.weight.toString()}
                          onChangeText={(value) => updateSet(exercise.id, set.id, 'weight', parseInt(value) || 0)}
                        />
                        <Text style={styles.unit}>lbs</Text>
                      </View>
                    ))}
                  </View>
                ))}
              </View>
            )}

            {/* Finish Workout Button */}
            <TouchableOpacity style={styles.finishButton} onPress={finishWorkout}>
              <Ionicons name="checkmark-circle" size={24} color="#fff" />
              <Text style={styles.finishButtonText}>Finish Workout</Text>
            </TouchableOpacity>
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f8f9fa',
  },
  scrollView: {
    flex: 1,
  },
  startContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 30,
  },
  startButton: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#007AFF',
    paddingHorizontal: 30,
    paddingVertical: 15,
    borderRadius: 25,
    gap: 10,
  },
  startButtonText: {
    color: '#fff',
    fontSize: 18,
    fontWeight: '600',
  },
  workoutContainer: {
    padding: 20,
  },
  workoutHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 20,
  },
  workoutTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    color: '#333',
  },
  workoutTime: {
    fontSize: 16,
    color: '#666',
  },
  categoriesContainer: {
    marginBottom: 20,
  },
  sectionTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    color: '#333',
    marginBottom: 15,
  },
  categoryButton: {
    backgroundColor: '#fff',
    paddingHorizontal: 20,
    paddingVertical: 10,
    borderRadius: 20,
    marginRight: 10,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  selectedCategory: {
    backgroundColor: '#007AFF',
  },
  categoryText: {
    fontSize: 14,
    fontWeight: '600',
    color: '#333',
  },
  selectedCategoryText: {
    color: '#fff',
